const input = $input.first().json;
const normalize = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('fr-FR').replace(/\b(sa|sas|sasu|sarl|eurl|scop|association|ei|eirl)\b/g, ' ').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const luhn = (digits) => { let sum = 0; let alt = false; for (let i = digits.length - 1; i >= 0; i--) { let n = Number(digits[i]); if (alt) { n *= 2; if (n > 9) n -= 9; } sum += n; alt = !alt; } return sum % 10 === 0; };
const sameLocation = (offer, candidate) => (offer.postal_code && candidate.postal_code && String(offer.postal_code) === String(candidate.postal_code)) || (normalize(offer.city) && normalize(offer.city) === normalize(candidate.city));
const candidateNameMatch = (offer, candidate) => normalize(offer.declared_company_name || offer.company_name) === normalize(candidate.legal_name);
const tradeNameMatch = (offer, candidate) => candidate.trade_name && normalize(offer.declared_company_name || offer.company_name) === normalize(candidate.trade_name);
const plans = [];
for (const offer of input.offers) {
  const sirene = input.sirene_results_by_offer_key[offer.offer_key] || { candidates: [], status: 'zero_result' };
  const candidates = sirene.candidates || [];
  const declaredDigits = String(offer.declared_siret || '').replace(/\D/g, '');
  const hasValidSiret = declaredDigits.length === 14 && luhn(declaredDigits);
  let method = 'unresolved'; let status = 'unresolved'; let score = 0; let reason = 'G8N_MATCH_LOCATION_ONLY_REJECTED'; let candidate = null;
  if (hasValidSiret && candidates.length === 1 && candidates[0].siret === declaredDigits) {
    candidate = candidates[0];
    if (candidate.establishment_status === 'open') { method = 'explicit_siret'; status = 'matched'; score = 95; reason = 'G8N_MATCH_EXPLICIT_SIRET'; }
    else { method = 'exact_name_closed_establishment'; status = 'ambiguous'; score = 64; reason = 'G8N_MATCH_CLOSED_ESTABLISHMENT_REVIEW'; }
  } else {
    const exactNameCandidates = candidates.filter((c) => candidateNameMatch(offer, c));
    const exactLocationCandidates = exactNameCandidates.filter((c) => sameLocation(offer, c));
    const trade = candidates.filter((c) => tradeNameMatch(offer, c) && sameLocation(offer, c));
    if (exactLocationCandidates.length === 1) {
      candidate = exactLocationCandidates[0];
      if (candidate.establishment_status === 'open') { method = offer.postal_code && String(offer.postal_code) === String(candidate.postal_code) ? 'exact_name_postal_code' : 'exact_name_city'; status = 'matched'; score = method === 'exact_name_postal_code' ? 87 : 85; reason = 'G8N_MATCH_EXACT_NAME_LOCATION'; }
      else { method = 'exact_name_closed_establishment'; status = 'ambiguous'; score = 64; reason = 'G8N_MATCH_CLOSED_ESTABLISHMENT_REVIEW'; }
    }
    else if (exactNameCandidates.length > 1) { method = 'multiple_exact_candidates'; status = 'ambiguous'; score = 59; reason = 'G8N_MATCH_HOMONYM_AMBIGUOUS'; }
    else if (trade.length === 1 && trade[0].establishment_status === 'open') { candidate = trade[0]; method = 'trade_name_establishment'; status = 'matched'; score = 82; reason = 'G8N_MATCH_TRADE_NAME_LOCATION'; }
    else if (trade.length > 1) { method = 'multiple_exact_candidates'; status = 'ambiguous'; score = 59; reason = 'G8N_MATCH_HOMONYM_AMBIGUOUS'; }
    else if (exactNameCandidates.length === 1) { candidate = exactNameCandidates[0]; method = 'exact_name_conflicting_location'; status = 'ambiguous'; score = 64; reason = 'G8N_MATCH_TOLERANT_AMBIGUOUS'; }
  }
  const companyKey = candidate?.siren ? `siren:${candidate.siren}` : null;
  const establishmentKey = candidate?.siret ? `siret:${candidate.siret}` : null;
  plans.push({ offer_key: offer.offer_key, match_key: `${offer.offer_key}:${input.match_rule_version}:${method}`, match_method: method, match_status: status, confidence: score, reason, match_rule_version: input.match_rule_version, company_key: companyKey, establishment_key: establishmentKey, candidate_siren: candidate?.siren || null, candidate_siret: candidate?.siret || null, evidence_json: JSON.stringify({ declared_company_name: offer.declared_company_name || offer.company_name || null, normalized_declared_company_name: normalize(offer.declared_company_name || offer.company_name), declared_city: offer.city || null, declared_postal_code: offer.postal_code || null, candidate, sirene_status: sirene.status }) });
}
return [{ json: { ...input, company_match_upsert_plans: plans, next_step: 'Review plans, then wire transactional Data Table upserts locally.' } }];

const input = $input.first().json;
const companyUpserts = [];
const establishmentUpserts = [];
for (const plan of input.company_match_upsert_plans || []) {
  if (plan.company_key) companyUpserts.push({ company_key: plan.company_key, siren: plan.candidate_siren, identity_confidence: plan.confidence, updated_at: new Date().toISOString() });
  if (plan.establishment_key) establishmentUpserts.push({ establishment_key: plan.establishment_key, company_key: plan.company_key, siret: plan.candidate_siret, siren: plan.candidate_siren, identity_confidence: plan.confidence, updated_at: new Date().toISOString() });
}
return [{ json: { ...input, transactional_write_order: ['companies', 'establishments', 'company_matches', 'job_offers'], company_upserts: companyUpserts, establishment_upserts: establishmentUpserts } }];
